// Validate loyalty event payload
const body = $json.body || $json;
const eventType = (body.event_type || '').toString(); // order_confirmed | order_cancelled | manual_award
const customerId = body.customer_id;
const orderId = body.order_id;
const orderAmount = Number(body.total_amount || 0); // in DA

if (!eventType || !customerId) {
  return [{ json: { _skip: true, reason: 'missing event_type or customer_id' }}];
}

// Points calculation: 1 point per 10 DA spent
const pointsEarned = eventType === 'order_confirmed' ? Math.floor(orderAmount / 10) : 0;

return [{ json: {
  eventType,
  customerId,
  orderId,
  orderAmount,
  pointsEarned,
  processedAt: new Date().toISOString()
}}];

// Compute new loyalty tier and points
const event = $('L0 — Validate Loyalty Event').item.json;
const customerRes = $json;
const attr = customerRes.data?.attributes || customerRes.data || {};

const currentPoints = Number(attr.loyalty_points || 0);
const currentTier = (attr.loyalty_tier || 'bronze').toString().toLowerCase();
const newPoints = currentPoints + event.pointsEarned;

// Tier thresholds (in points)
const TIERS = [
  { name: 'diamond', min: 5000 },
  { name: 'gold',    min: 2000 },
  { name: 'silver',  min: 500  },
  { name: 'bronze',  min: 0    }
];

const newTier = TIERS.find(t => newPoints >= t.min)?.name || 'bronze';
const tierUpgraded = newTier !== currentTier && 
  TIERS.findIndex(t => t.name === newTier) < TIERS.findIndex(t => t.name === currentTier);

// Tier emoji map
const TIER_EMOJI = { bronze: '🥉', silver: '🥈', gold: '🥇', diamond: '💎' };

return [{ json: {
  customerId: event.customerId,
  customerPhone: attr.phone,
  customerName: attr.name || 'Client',
  currentPoints,
  newPoints,
  pointsEarned: event.pointsEarned,
  currentTier,
  newTier,
  tierUpgraded,
  tierEmoji: TIER_EMOJI[newTier] || '🥉',
  orderId: event.orderId,
  orderAmount: event.orderAmount
}}];

